/**
 * Handles toggling of editing tools based on the triggered event.
 * Events can come flying from anywhere, but most likely editor toolbar or MapTools toolbar
 * @param {Event} e - The triggered event containing tool details.
 */
function onToggleEdit(e) {
  const { detail: { tool } } = e;
  e.stopPropagation();
  if (tool === 'draw' && allowCreate) {
    if (hasDraw === false) {
      setInteractions();
      startDraw();
    } else {
      cancelDraw();
    }
  } else if (tool === 'attribute' && allowEditAttributes) {
    editAttributes();
  } else if (tool === 'delete' && allowDelete) {
    onDeleteSelected();
  } else if (tool === 'edit') {
    setEditLayer(e.detail.currentLayer);
  } else if (tool === 'cancel') {
    removeInteractions();
  } else if (tool === 'save') {
    saveFeatures();
  } else if (tool === 'abortSession') {
    abortSession();
  } else if (tool === 'undo') {
    undo();
  } else if (tool === 'redo') {
    redo();
  }
}

